package com.bank.duplicate;

import java.math.BigDecimal;
import java.util.HashSet;
import java.util.Set;
import java.util.logging.Logger;

// Guards against duplicate transaction identifiers for National Bank of India.
public class DuplicateGuard {
    private static final Logger log = Logger.getLogger(DuplicateGuard.class.getName());

    // True if any id repeats. O(n) average, early exit on first duplicate.
    public boolean hasDuplicate(String[] ids) {
        if (ids == null || ids.length < 2) return false;
        Set<String> seen = new HashSet<>(ids.length * 2);  // pre-size to avoid rehash
        for (String id : ids) {
            if (!seen.add(id)) {              // add returns false → already present
                log.warning(() -> "Duplicate transaction id detected: " + id);
                return true;                  // early exit
            }
        }
        log.info("No duplicate identifiers in batch");
        return false;
    }

    // Numeric duplicate check: normalise scale so 100 and 100.00 are equal.
    public boolean hasNumericDuplicate(BigDecimal[] amounts) {
        if (amounts == null || amounts.length < 2) return false;
        Set<BigDecimal> seen = new HashSet<>(amounts.length * 2);
        for (BigDecimal a : amounts) {
            BigDecimal key = a.stripTrailingZeros();   // 100.00 → 1E+2 canonical
            if (!seen.add(key)) {
                log.warning(() -> "Numeric duplicate amount detected: " + a);
                return true;
            }
        }
        return false;
    }
}
