package com.bank.duplicate;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: guard a transaction batch against duplicates.
public class DuplicateDemo {
    private static final Logger log = Logger.getLogger(DuplicateDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        DuplicateGuard guard = new DuplicateGuard();

        String[] cleanBatch = {"TXN-001", "TXN-002", "TXN-003"};
        String[] dupBatch   = {"TXN-001", "TXN-002", "TXN-001"};  // TXN-001 repeats

        log.info(() -> "Clean batch has duplicate? " + guard.hasDuplicate(cleanBatch));
        log.info(() -> "Dup batch has duplicate? " + guard.hasDuplicate(dupBatch));

        BigDecimal[] amounts = { new BigDecimal("100"), new BigDecimal("100.00") };
        log.info(() -> "Numerically equal amounts duplicate? "
                + guard.hasNumericDuplicate(amounts));
    }
}
